// Section: wire_class

class NovaCoreWire implements BaseWire {
  factory NovaCoreWire.fromExternalLibrary(ExternalLibrary lib) =>
      NovaCoreWire(lib.ffiDynamicLibrary);

  /// Holds the symbol lookup function.
  final ffi.Pointer<T> Function<T extends ffi.NativeType>(String symbolName)
  _lookup;

  /// The symbols are looked up in [dynamicLibrary].
  NovaCoreWire(ffi.DynamicLibrary dynamicLibrary)
    : _lookup = dynamicLibrary.lookup;
}
